	"cost_records":                   {"ai_gateway", "confidential"},
	"risk_rules":                     {"ai_gateway", "internal"},
	"risk_hits":                      {"ai_gateway", "confidential"},
	"chat_sessions":                  {"ai_gateway", "confidential"},
	"chat_messages":                  {"ai_gateway", "confidential"},
	"instance_gateway_token_aliases": {"ai_gateway", "secret"},
}

var hashPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)
var evidencePattern = regexp.MustCompile(`^sev_[A-Za-z0-9_-]+$`)

// CaptureScope is the immutable result of matching a frozen registry to an
// independently reviewed deployment digest. Its fields cannot be changed by
// a caller after construction.
type CaptureScope struct {
	tables      []string
	registrySHA string
	schemaSHA   string
}

// NewPinnedCaptureScope is the only construction path for a collector or
// verifier scope. expectedSHA256 must come from trusted deployment state,
// never from the registry bytes or task request being checked.
func NewPinnedCaptureScope(registryJSON []byte, expectedSHA256 string) (*CaptureScope, error) {
	if !hashPattern.MatchString(expectedSHA256) {
		return nil, errors.New("invalid A business registry pin")
	}
	digest := sha256.Sum256(registryJSON)
	if hex.EncodeToString(digest[:]) != expectedSHA256 {
		return nil, errors.New("A business registry pin mismatch")
	}
	tableNames, schemaSHA, err := parseCaptureTableAllowlist(registryJSON)
	if err != nil {
		return nil, err
	}
	return &CaptureScope{tables: tableNames, registrySHA: expectedSHA256, schemaSHA: schemaSHA}, nil
}

// RegistrySHA256 and SchemaSHA256 identify the pinned registry bytes and its
// observed source schema. They are metadata, not a capture certificate.
func (s *CaptureScope) RegistrySHA256() string {
	if s == nil {
		return ""
	}
	return s.registrySHA
}

func (s *CaptureScope) SchemaSHA256() string {
	if s == nil {
		return ""
	}
	return s.schemaSHA
}

func (s *CaptureScope) Tables() []string {
	if s == nil {
		return nil
	}
	return append([]string(nil), s.tables...)
}

type registry struct {
	Kind            string `json:"kind"`
	RegistryVersion string `json:"registry_version"`
	ContractVersion string `json:"contract_version"`
	ContractStatus  string `json:"contract_status"`
	SchemaHash      struct {
		Algorithm string  `json:"algorithm"`
		Status    string  `json:"status"`
		Hash      *string `json:"hash"`
		Evidence  *struct {
			PublicID string `json:"public_id"`
			SHA256   string `json:"sha256"`
		} `json:"evidence"`
	} `json:"schema_hash"`
	Summary struct {
		ObjectCount        int `json:"object_count"`
		PolicyRecorded     int `json:"policy_recorded"`
		PolicyPending      int `json:"policy_pending"`
		CrossReviewPending int `json:"cross_review_pending"`
	} `json:"summary"`
	Objects []struct {
		ObjectType             string   `json:"object_type"`
		Name                   string   `json:"name"`
		Owner                  string   `json:"owner"`
		Category               string   `json:"category"`
		Classification         *string  `json:"data_classification"`
		BackupStrategy         string   `json:"backup_strategy"`
		RestoreStrategy        string   `json:"restore_strategy"`
		NormalizerID           string   `json:"normalizer_id"`
		VerifierID             string   `json:"verifier_id"`
		DecisionStatus         string   `json:"decision_status"`
		RequiredCrossReviewers []string `json:"required_cross_reviewers"`
		ApprovedCrossReviewers []string `json:"approved_cross_reviewers"`
	} `json:"objects"`
}

// parseCaptureTableAllowlist validates registry structure. It alone does not
// establish provenance; only NewPinnedCaptureScope can authorize SQL use.
func parseCaptureTableAllowlist(registryJSON []byte) ([]string, string, error) {
	var r registry
	if err := json.Unmarshal(registryJSON, &r); err != nil {
		return nil, "", fmt.Errorf("decode schema registry: %w", err)
	}
	if r.Kind != "system_backup_schema_registry" || r.RegistryVersion != "system-backup-schema-registry.v1" ||
		r.ContractVersion != "system-backup-plan.v12" || r.ContractStatus != "frozen" {
		return nil, "", errors.New("A business capture requires frozen v12 schema registry")
	}
	if r.SchemaHash.Algorithm != "sha256-information-schema-canonical-v1" || r.SchemaHash.Status != "observed" ||
		r.SchemaHash.Hash == nil || !hashPattern.MatchString(*r.SchemaHash.Hash) || r.SchemaHash.Evidence == nil ||
		!evidencePattern.MatchString(r.SchemaHash.Evidence.PublicID) || !hashPattern.MatchString(r.SchemaHash.Evidence.SHA256) {
		return nil, "", errors.New("A business capture requires observed schema evidence")
	}
	if r.Summary.ObjectCount != len(r.Objects) || r.Summary.PolicyRecorded != len(r.Objects) ||
		r.Summary.PolicyPending != 0 || r.Summary.CrossReviewPending != 0 {
		return nil, "", errors.New("A business capture requires complete registry summary")
	}
	seenObjects := make(map[string]struct{}, len(r.Objects))
	seenTables := make(map[string]struct{}, len(tables))
	for _, object := range r.Objects {
		key := object.ObjectType + ":" + object.Name
		if object.ObjectType == "" || object.Name == "" {
			return nil, "", errors.New("unnamed schema object")
		}
		if _, exists := seenObjects[key]; exists {
			return nil, "", fmt.Errorf("duplicate schema object %s", key)
		}
		seenObjects[key] = struct{}{}
		if object.DecisionStatus != "frozen" || !reviewed(object.Owner, object.RequiredCrossReviewers, object.ApprovedCrossReviewers) {
			return nil, "", fmt.Errorf("unfrozen or unreviewed schema object %s", key)
		}
		policy, named := tables[object.Name]
		inCategory := object.Category == "users" || object.Category == "ai_gateway"
		// Other A-owned categories, such as system control objects, are outside
		// this collector. A table name or category collision must still fail.
		if !named && !inCategory {
			continue
		}
		if !named || object.ObjectType != "table" || object.Owner != "A" || object.Category != policy.category ||
			object.Classification == nil || *object.Classification != policy.classification ||
			object.BackupStrategy != "mysql_dump" || object.RestoreStrategy != "normalize" ||
			object.NormalizerID != policy.category+"."+object.Name+".normalize.v1" ||
			object.VerifierID != policy.category+"."+object.Name+".verify.v1" || len(object.RequiredCrossReviewers) == 0 {
			return nil, "", fmt.Errorf("A business capture policy mismatch at %s", key)
		}
		seenTables[object.Name] = struct{}{}
	}
	if len(seenTables) != len(tables) {
		return nil, "", fmt.Errorf("A business capture scope incomplete: %d of %d tables", len(seenTables), len(tables))
	}
	result := make([]string, 0, len(tables))
	for table := range seenTables {
		result = append(result, table)
	}
	sort.Strings(result)
	return result, *r.SchemaHash.Hash, nil
}

func reviewed(owner string, required, approved []string) bool {
	valid := func(role string) bool { return role == "A" || role == "B" || role == "C" || role == "D" }
	if !valid(owner) || len(required) != len(approved) {
		return false
	}
	want := make(map[string]struct{}, len(required))
	for _, role := range required {
		if !valid(role) || role == owner {
			return false
		}
		if _, duplicate := want[role]; duplicate {
			return false
		}
		want[role] = struct{}{}
	}
	seen := make(map[string]struct{}, len(approved))
	for _, role := range approved {
		if _, expected := want[role]; !expected {
			return false
		}
		if _, duplicate := seen[role]; duplicate {
			return false
		}
		seen[role] = struct{}{}
	}
	return true
}

// TableCount contains no business row contents, identifiers or secret values.
type TableCount struct {
	Table string `json:"table"`
	Rows  int64  `json:"rows"`
}

// SourceSnapshot is a single source transaction's redacted statistics. It is
// not evidence that any dump captured those rows or used the same checkpoint.
type SourceSnapshot struct {
	Tables []TableCount `json:"tables"`
	CostAggregateSHA256 string `json:"cost_aggregate_sha256"`
}

type SQLCountCollector struct{ DB *sql.DB }

// CollectSnapshot returns no partial result if any table or transaction fails.
func (c SQLCountCollector) CollectSnapshot(ctx context.Context, scope *CaptureScope) (SourceSnapshot, error) {
	if ctx == nil {
		return SourceSnapshot{}, errors.New("nil A business snapshot context")
	}
	if err := ctx.Err(); err != nil {
		return SourceSnapshot{}, err
	}
	if scope == nil || len(scope.tables) != len(tables) || !hashPattern.MatchString(scope.registrySHA) || !hashPattern.MatchString(scope.schemaSHA) {
		return SourceSnapshot{}, errors.New("A business pinned scope required")
	}
	if c.DB == nil {
		return SourceSnapshot{}, errors.New("nil A business database")
	}
	tx, err := c.DB.BeginTx(ctx, &sql.TxOptions{ReadOnly: true, Isolation: sql.LevelRepeatableRead})
	if err != nil {
		return SourceSnapshot{}, fmt.Errorf("begin A business snapshot: %w", err)
	}
	defer tx.Rollback()
	snapshot := SourceSnapshot{Tables: make([]TableCount, 0, len(scope.tables))}
	var total int64
	for _, table := range scope.tables {
		var engine string
		if err := tx.QueryRowContext(ctx, `SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND TABLE_TYPE = 'BASE TABLE'`, table).Scan(&engine); err != nil {
			return SourceSnapshot{}, fmt.Errorf("inspect A business table %s: %w", table, err)
		}
		if !strings.EqualFold(engine, "InnoDB") {
			return SourceSnapshot{}, fmt.Errorf("A business table %s is not transactional InnoDB", table)
		}
		// Table identifiers come exclusively from the closed allowlist above.
		var rows int64
		if err := tx.QueryRowContext(ctx, "SELECT COUNT(*) FROM `"+table+"`").Scan(&rows); err != nil {
			return SourceSnapshot{}, fmt.Errorf("count A business table %s: %w", table, err)
		}
		if rows < 0 || rows > math.MaxInt64-total {
			return SourceSnapshot{}, fmt.Errorf("invalid A business count for %s", table)
		}
		total += rows
		snapshot.Tables = append(snapshot.Tables, TableCount{Table: table, Rows: rows})
	}
	snapshot.CostAggregateSHA256, err = readCostAggregateHash(ctx, tx, snapshotCostRows(snapshot))
	if err != nil { return SourceSnapshot{}, err }
	if err := tx.Commit(); err != nil {
		return SourceSnapshot{}, fmt.Errorf("commit A business snapshot: %w", err)
	}
	if err := ctx.Err(); err != nil {
		return SourceSnapshot{}, err
	}
	return snapshot, nil
}

package systembackupbusinessa

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"math/big"
	"sort"
	"strings"
)

// Cost summaries are grouped by exact currency bytes, never by the target's
// case-insensitive collation. The bound rejects excess groups, not a truncated
// successful summary. Only the digest is exposed in snapshots/checks.
const maxCostAggregateCurrencies = 256

const costAggregateQuery = `SELECT BINARY currency, COUNT(*), COUNT(actual_cost),
CAST(SUM(prompt_tokens) AS CHAR), CAST(SUM(completion_tokens) AS CHAR), CAST(SUM(total_tokens) AS CHAR),
CAST(SUM(input_unit_price) AS CHAR), CAST(SUM(output_unit_price) AS CHAR), CAST(SUM(estimated_cost) AS CHAR),
CAST(COALESCE(SUM(actual_cost),CAST(0 AS DECIMAL(18,8))) AS CHAR), CAST(SUM(internal_cost) AS CHAR),
SUM(prompt_tokens IS NULL OR prompt_tokens<0 OR completion_tokens IS NULL OR completion_tokens<0 OR total_tokens IS NULL OR total_tokens<prompt_tokens OR total_tokens<completion_tokens OR input_unit_price IS NULL OR input_unit_price<0 OR output_unit_price IS NULL OR output_unit_price<0 OR estimated_cost IS NULL OR estimated_cost<0 OR actual_cost<0 OR internal_cost IS NULL OR internal_cost<0)
FROM cost_records GROUP BY BINARY currency ORDER BY BINARY currency LIMIT 257`

type costCurrencyAggregate struct {
	Currency string `json:"currency"`
	Rows int64 `json:"rows"`
	ActualCostCount int64 `json:"actual_cost_count"`
	PromptTokens string `json:"prompt_tokens"`
	CompletionTokens string `json:"completion_tokens"`
	TotalTokens string `json:"total_tokens"`
	InputUnitPrice string `json:"input_unit_price"`
	OutputUnitPrice string `json:"output_unit_price"`
	EstimatedCost string `json:"estimated_cost"`
	ActualCost string `json:"actual_cost"`
	InternalCost string `json:"internal_cost"`
}

func costUnsigned(raw string, scale int) (*big.Int, bool) {
	if len(raw)>48 { return nil,false }
	whole,fraction,dot:=strings.Cut(raw,".")
	if whole=="" || len(whole)>1&&whole[0]=='0' || (scale==0&&dot) || (scale>0&&(!dot||len(fraction)!=scale)) { return nil,false }
	for _,part:=range []string{whole,fraction} { for _,r:=range part { if r<'0'||r>'9' {return nil,false} } }
	n,ok:=new(big.Int).SetString(whole+fraction,10)
	return n,ok
}

func costFixed(n *big.Int) string {
	s:=n.String()
	if len(s)<=8 {s=strings.Repeat("0",9-len(s))+s}
	return s[:len(s)-8]+"."+s[len(s)-8:]
}

func costAggregateHash(groups []costCurrencyAggregate, expectedRows int64) (string,error) {
	if expectedRows<0 || len(groups)>maxCostAggregateCurrencies {return "",ErrInvalidSnapshot}
	if groups==nil {groups=[]costCurrencyAggregate{}}
	var rows int64
	previous:=""
	maxPrice,_:=new(big.Int).SetString("999999999999999999",10)
	for i,g:=range groups {
		if !validUserRestoreText(g.Currency,16) || i>0&&g.Currency<=previous || g.Rows<=0 || g.Rows>math.MaxInt64-rows || g.ActualCostCount<0 || g.ActualCostCount>g.Rows {return "",ErrInvalidSnapshot}
		previous=g.Currency;rows+=g.Rows
		var tokens [3]*big.Int
		for j,s:=range []string{g.PromptTokens,g.CompletionTokens,g.TotalTokens} {
			n,ok:=costUnsigned(s,0);limit:=new(big.Int).Mul(big.NewInt(g.Rows),big.NewInt(math.MaxInt32))
			if !ok||n.Cmp(limit)>0{return "",ErrInvalidSnapshot};tokens[j]=n
		}
		if tokens[2].Cmp(tokens[0])<0||tokens[2].Cmp(tokens[1])<0{return "",ErrInvalidSnapshot}
		for j,s:=range []string{g.InputUnitPrice,g.OutputUnitPrice,g.EstimatedCost,g.ActualCost,g.InternalCost} {
			n,ok:=costUnsigned(s,8);count:=g.Rows;if j==3 {count=g.ActualCostCount}
			limit:=new(big.Int).Mul(big.NewInt(count),maxPrice)
			if !ok||n.Cmp(limit)>0{return "",ErrInvalidSnapshot}
		}
	}
	if rows!=expectedRows{return "",ErrInvalidSnapshot}
	b,err:=json.Marshal(groups);if err!=nil{return "",ErrInvalidSnapshot}
	h:=sha256.Sum256(append([]byte("cost-record-aggregate-v1\n"),b...))
	return hex.EncodeToString(h[:]),nil
}

func readCostAggregateHash(ctx context.Context, tx *sql.Tx, expectedRows int64) (string,error) {
	rows,err:=tx.QueryContext(ctx,costAggregateQuery)
	if err!=nil{return "",fmt.Errorf("query A cost aggregates: %w",err)}
	defer rows.Close()
	groups:=make([]costCurrencyAggregate,0)
	for rows.Next() {
		if len(groups)==maxCostAggregateCurrencies{return "",ErrInvalidSnapshot}
		var g costCurrencyAggregate;var violations int64
		if err:=rows.Scan(&g.Currency,&g.Rows,&g.ActualCostCount,&g.PromptTokens,&g.CompletionTokens,&g.TotalTokens,&g.InputUnitPrice,&g.OutputUnitPrice,&g.EstimatedCost,&g.ActualCost,&g.InternalCost,&violations);err!=nil{return "",fmt.Errorf("scan A cost aggregates: %w",err)}
		if violations!=0{return "",ErrInvalidSnapshot}
		groups=append(groups,g)
	}
	if err:=rows.Err();err!=nil{return "",fmt.Errorf("read A cost aggregates: %w",err)}
	if err:=rows.Close();err!=nil{return "",fmt.Errorf("close A cost aggregates: %w",err)}
	return costAggregateHash(groups,expectedRows)
}

// This projection contains no identity or mutable pointer shared with proofs.
// Source values and normalized rows must independently produce the same digest
// as the authenticated SQL snapshot. It does not authorize target writes.
func costSourceAggregateHash(sources []CostRecordRestoreSource) (string,error) {
	byCurrency:=make(map[string]*costCurrencyAggregate)
	for _,s:=range sources {
		if !validUserRestoreText(s.Currency,16)||s.PromptTokens<0||s.CompletionTokens<0||s.TotalTokens<s.PromptTokens||s.TotalTokens<s.CompletionTokens||s.PromptTokens>math.MaxInt32||s.CompletionTokens>math.MaxInt32||s.TotalTokens>math.MaxInt32{return "",ErrInvalidSnapshot}
		g:=byCurrency[s.Currency]
		if g==nil {
			if len(byCurrency)==maxCostAggregateCurrencies{return "",ErrInvalidSnapshot}
			g=&costCurrencyAggregate{Currency:s.Currency,PromptTokens:"0",CompletionTokens:"0",TotalTokens:"0",InputUnitPrice:"0.00000000",OutputUnitPrice:"0.00000000",EstimatedCost:"0.00000000",ActualCost:"0.00000000",InternalCost:"0.00000000"};byCurrency[s.Currency]=g
		}
		g.Rows++
		for i,dst:=range []*string{&g.PromptTokens,&g.CompletionTokens,&g.TotalTokens} {
			n,_:=costUnsigned(*dst,0);n.Add(n,big.NewInt(int64([]int{s.PromptTokens,s.CompletionTokens,s.TotalTokens}[i])));*dst=n.String()
		}
		actual:="0";if s.ActualCost!=nil{actual=*s.ActualCost;g.ActualCostCount++}
		for i,dst:=range []*string{&g.InputUnitPrice,&g.OutputUnitPrice,&g.EstimatedCost,&g.ActualCost,&g.InternalCost} {
			canonical,ok:=canonicalLLMPrice([]string{s.InputUnitPrice,s.OutputUnitPrice,s.EstimatedCost,actual,s.InternalCost}[i]);if !ok{return "",ErrInvalidSnapshot}
			n,_:=costUnsigned(*dst,8);value,_:=costUnsigned(canonical,8);n.Add(n,value);*dst=costFixed(n)
		}
	}
	groups:=make([]costCurrencyAggregate,0,len(byCurrency));for _,g:=range byCurrency{groups=append(groups,*g)}
	sort.Slice(groups,func(i,j int)bool{return groups[i].Currency<groups[j].Currency})
	return costAggregateHash(groups,int64(len(sources)))
}

func normalizedCostAggregateHash(rows []NormalizedCostRecord) (string,error) {
	sources:=make([]CostRecordRestoreSource,len(rows))
	for i,r:=range rows {sources[i]=CostRecordRestoreSource{Currency:r.Currency,PromptTokens:r.PromptTokens,CompletionTokens:r.CompletionTokens,TotalTokens:r.TotalTokens,InputUnitPrice:r.InputUnitPrice,OutputUnitPrice:r.OutputUnitPrice,EstimatedCost:r.EstimatedCost,ActualCost:r.ActualCost,InternalCost:r.InternalCost}}
	return costSourceAggregateHash(sources)
}

func snapshotCostRows(snapshot SourceSnapshot) int64 {
	for _,t:=range snapshot.Tables {if t.Table=="cost_records"{return t.Rows}}
	return -1
}

func cloneSourceSnapshot(snapshot SourceSnapshot) SourceSnapshot {
	snapshot.Tables=append([]TableCount(nil),snapshot.Tables...)
	return snapshot
}

